/*
 * A183421  Second of two complementary trees generated by the squares; The
 *          other tree is A183420.
 * https://oeis.org/A183421
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   not stated
 * Range:     u8 n <= 7, u16 n <= 15, u32 n <= 31, u64 n <= 31, u128 n <= 31,
 *            big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A183421
   Offset: 1
   Definition (recursive, tree based on the squares):

   a(1) = 1
   For n > 1, let k = ⌊n/2⌋.
   • If n is even (n = 2k):
         a(n) = ((a(k) + 2)^2) – 2
   • If n is odd  (n = 2k + 1):
         d = round( sqrt( a(k) + 2 ) )      // nearest integer to the square root
         a(n) = a(k) + d
*/

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include "../utils/floor_sqrt.h"

seq_t a(idx_t n)
{
    /* Static array for memoisation: indices 1 … current_max are filled. */
    static seq_t *cache   = NULL;
    static size_t cache_cap = 0;
    static idx_t  cache_last = 0;

    if (n == 0) /* offset is 1 – behaviour for n < 1 is undefined */
        return (seq_t)0;

    /* Allocate or grow the cache */
    if (cache == NULL) {
        cache_cap = 128;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
    } else if ((size_t)n >= cache_cap) {
        size_t new_cap = cache_cap;
        while ((size_t)n >= new_cap)
            new_cap <<= 1;
        cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        cache_cap = new_cap;
    }

    /* Compute missing values up to n */
    for (idx_t i = cache_last + 1; i <= n; ++i) {
        if (i == 1) {
            cache[1] = (seq_t)1;
            continue;
        }

        idx_t k = i >> 1;           /* floor(i/2) */
        seq_t parent = cache[k];

        if ((i & 1) == 0) { /* even index: 2k */
            seq_t t = parent + (seq_t)2;
            t = t * t;
            t -= (seq_t)2;
            cache[i] = t;
        } else { /* odd index: 2k+1 */
            seq_t y   = parent + (seq_t)2;            /* = a(k)+2 */
            seq_t sq  = floor_sqrt(y);                /* floor( sqrt(y) )   */
            seq_t sq2 = sq * sq;                      /* sq^2               */
            seq_t sq3 = (sq + (seq_t)1) * (sq + (seq_t)1);  /* (sq+1)^2      */

            seq_t diff;
            /* nearest integer to sqrt(y) */
            if ((y - sq2) >= (sq3 - y))
                diff = sq + (seq_t)1;
            else
                diff = sq;

            cache[i] = parent + diff;
        }
    }

    cache_last = n;
    return cache[n];
}
